    uint256 constant IC1y = 5690672961714275696236744406310616369763880710462357572746045302081069633603;

    uint256 constant IC2x = 21731867627322620252249980000871618799089455155513589921238037757798220101581;
    uint256 constant IC2y = 9027162498240997639287573350219575317441535096931776151326573103149237309851;


    // Memory data
    uint16 constant pVk = 0;
    uint16 constant pPairing = 128;

    uint16 constant pLastMem = 896;

    function verifyProof(uint[2] calldata _pA, uint[2][2] calldata _pB, uint[2] calldata _pC, uint[2] calldata _pubSignals) public view returns (bool) {
        assembly {
            function checkField(v) {
                if iszero(lt(v, r)) {
                    mstore(0, 0)
                    return(0, 0x20)
                }
            }

            // G1 function to multiply a G1 value(x,y) to value in an address
            function g1_mulAccC(pR, x, y, s) {
                let success
                let mIn := mload(0x40)
